create table company (arn_issue_date date, created_time timestamp(6), last_updated_time timestamp(6), sac_code bigint, id uuid not null, arn varchar(255), business_category varchar(255), business_description varchar(255), code varchar(255) not null unique, created_by varchar(255), email varchar(255) not null, last_updated_by varchar(255), mobile varchar(255) not null, name varchar(255) not null unique, pan varchar(255) not null unique, status varchar(255) not null, telephone varchar(255) not null, website varchar(255), primary key (id));
create table company_address (created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, address_line_1 varchar(255) not null, address_line_2 varchar(255), branch_name varchar(255), city varchar(255) not null, country varchar(255) not null, created_by varchar(255), last_updated_by varchar(255), post_code varchar(255) not null, state varchar(255) not null, town varchar(255), type varchar(255) not null check (type in ('Primary','Secondary','Other')), primary key (id), unique (company_id, type));
create table company_event (date_and_time date not null, created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, assign_to varchar(255) not null, created_by varchar(255), event_description varchar(255) not null, event_type varchar(255) not null check (event_type in ('Birthday','Anniversary','Release','MeetingTownHall')), last_updated_by varchar(255), status varchar(255) not null, primary key (id));
create table company_file (created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, created_by varchar(255), description varchar(255), file_name varchar(255) not null, last_updated_by varchar(255), primary key (id));
create table company_gst (created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, created_by varchar(255), last_updated_by varchar(255), location varchar(255) not null, number varchar(255) not null, primary key (id), unique (company_id, number));
create table company_holiday (date date not null, deleted boolean not null, created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, created_by varchar(255), description varchar(255) not null, last_updated_by varchar(255), location varchar(255) not null, primary key (id), unique (date, description));
create table company_image (created_time timestamp(6), last_updated_time timestamp(6), size bigint not null, company_id uuid unique, id uuid not null, content_type varchar(255) not null, created_by varchar(255), last_updated_by varchar(255), name varchar(255) not null, content bytea not null, primary key (id));
create table company_lnf_plan (end_date date, start_date date, created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, lnf_plan_id uuid not null, created_by varchar(255), last_updated_by varchar(255), status varchar(255) not null check (status in ('ACTIVE','CANCELLED')), primary key (id));
create table company_lnf_plan_audit (end_date date, start_date date, created_time timestamp(6), last_updated_time timestamp(6), company_lnf_plan_id uuid not null, id uuid not null, created_by varchar(255), last_updated_by varchar(255), status varchar(255) not null, primary key (id));
create table company_notes (created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, created_by varchar(255), last_updated_by varchar(255), notes varchar(255) not null, primary key (id));
create table company_policy (created_time timestamp(6), last_updated_time timestamp(6), size bigint not null, company_id uuid not null, id uuid not null, content_type varchar(255) not null, created_by varchar(255), last_updated_by varchar(255), name varchar(255) not null unique, content bytea not null, primary key (id), unique (company_id, name));
create table lnf_plan (created_time timestamp(6), last_updated_time timestamp(6), id uuid not null, created_by varchar(255), description varchar(255), last_updated_by varchar(255), plan_name varchar(255) not null unique, primary key (id));
create table task (due_date date not null, remind_me date not null, created_time timestamp(6), last_updated_time timestamp(6), id uuid not null, created_by varchar(255), description varchar(255) not null, last_updated_by varchar(255), status varchar(255) not null check (status in ('TODO','IN_PROGRESS','COMPLETED','CANCELLED')), title varchar(255) not null, primary key (id));
create table theme (created_time timestamp(6), last_updated_time timestamp(6), company_id uuid not null, id uuid not null, created_by varchar(255), last_updated_by varchar(255), type varchar(255) not null check (type in ('PRIMARY','SECONDARY','SUCCESS','ERROR','WARNING','INFO')), value varchar(255) not null, primary key (id));
